"""Exact plugin UI + captured SDK new-session dispatch; no external model request."""
from pathlib import Path
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from playwright.sync_api import sync_playwright
from browser_support import browser_options
import json,threading,traceback,sys,hashlib
ROOT=Path(__file__).resolve().parents[1]
OUT=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'evidence/browser/draft-session'
OUT.mkdir(parents=True,exist_ok=True)
BUILD=json.loads((ROOT/'evidence/browser/build.json').read_text())
REPORT={'bundleSha256':BUILD['pluginSha256'],'boundary':'Production bundle in an SDK fixture; new-session prompt captured without a model/backend call','checks':[],'pageErrors':[]}
class Handler(SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(ROOT),**kw)
 def log_message(self,*a):pass
server=ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start()
def check(name,ok,detail=None):
 REPORT['checks'].append({'name':name,'pass':bool(ok),'detail':detail})
 if not ok:raise AssertionError(name+': '+str(detail))
try:
 with sync_playwright() as pw:
  browser=pw.chromium.launch(**browser_options());page=browser.new_page(viewport={'width':1500,'height':1000});page.set_default_timeout(10000)
  page.on('pageerror',lambda e:REPORT['pageErrors'].append(str(e)))
  try:
   check('Exact built plugin',hashlib.sha256(Path(BUILD['pluginFile']).read_bytes()).hexdigest()==BUILD['pluginSha256'])
   page.goto(f'http://127.0.0.1:{server.server_port}/proof/workspace-browser.html');page.get_by_role('button',name='Sound Draft',exact=True).wait_for()
   check('Only Sound Design and Compose navigation remain',page.locator('.ss-task-switcher').inner_text().splitlines()==['Sound Design','Compose'])
   check('Legacy testing route is not registered',page.evaluate("(()=>{try{proof.showRoute('/sonic-ui/legacy');return false}catch{return true}})()"))
   page.get_by_role('button',name='Sound Draft',exact=True).click();page.get_by_role('dialog').wait_for()
   start=page.get_by_role('button',name='Generate sound',exact=True)
   check('Blank requests cannot start generation',start.is_disabled())
   request='A warm, rounded confirmation bell with a very short glass tail'
   page.get_by_role('textbox',name='Describe the sound',exact=True).fill(request)
   page.evaluate("window.oldSessionDraft='Keep my unsent message';window.proofBackgroundHold=true")
   before=page.evaluate('JSON.stringify(proof.getDoc())')
   start.click();page.wait_for_function("proofBackgroundCalls.some(c=>c.method==='prompt.submit')")
   check('Draft runs without navigation or composer writes',page.get_by_role('dialog').is_visible() and page.evaluate('window.proofDraftSessions?.length??0')==0 and page.evaluate('oldSessionDraft')=='Keep my unsent message')
   check('One request uses an exact retained profile route',page.evaluate("proofBackgroundLeases===1&&proofBackgroundCalls.filter(c=>c.method==='prompt.submit').length===1&&proofBackgroundCalls.every(c=>c.route.connectionId==='local'&&c.route.profile==='default')"))
   prompt=page.evaluate("proofBackgroundCalls.find(c=>c.method==='prompt.submit').params.text")
   check('Prompt includes request schema starting patch and calibrated DSP limits',request in prompt and 'Exact JSON Schema:' in prompt and 'Starting patch:' in prompt and '0.11 safety gain' in prompt)
   check('Current sound stays unchanged while designing',page.evaluate('JSON.stringify(proof.getDoc())')==before)
   page.get_by_role('button',name='Close dialog',exact=True).click();page.evaluate('proof.leaveStudio()');page.get_by_role('region',name='Outside Studio',exact=True).wait_for()
   page.evaluate("proof.showRoute('/sonic-ui')");page.get_by_role('button',name='Sound Draft',exact=True).click()
   check('Pending background work survives leaving and reentering Studio',page.get_by_role('button',name='Cancel draft',exact=True).is_visible())
   page.evaluate('window.proofBackgroundHold=false');page.get_by_role('heading',name='Fine tune',exact=True).wait_for()
   page.wait_for_function('proofBackgroundLeases===0')
   check('Ready draft closes its runtime and releases the socket',page.evaluate('proof.getBackground().closed'))
   check('Generated features are shown for fine tuning',page.locator('.ss-draft-features').inner_text().find('voice')>=0)
   cutoff=page.locator('input[data-parameter-id="ft-cutoff"]');old_cutoff=float(cutoff.input_value());cutoff.focus();cutoff.press('ArrowLeft')
   page.wait_for_function("(old)=>Number(document.querySelector('input[data-parameter-id=ft-cutoff]').value)!==old",arg=old_cutoff)
   check('Fine tuning edits a draft while the current sound stays unchanged',float(cutoff.input_value())!=old_cutoff and page.evaluate('JSON.stringify(proof.getDoc())')==before,{'old':old_cutoff,'new':cutoff.input_value(),'disabled':page.locator('input[data-parameter-id=ft-cutoff]').is_disabled(),'review':page.locator('.ss-draft-review').inner_text(),'docBefore':before,'docAfter':page.evaluate('JSON.stringify(proof.getDoc())')})
   expected_cutoff=float(cutoff.input_value())
   for section in ['Envelope','Voices','Movement','Effects']:
    page.get_by_role('navigation',name='Fine tune sections').get_by_role('button',name=section,exact=True).click()
    check('Fine tune section: '+section,page.locator('.ss-draft-fields').is_visible())
   effect=page.locator('.ss-draft-fields input[type=checkbox]').first;effect.uncheck();check('Bypassed generated effects remain editable',effect.is_visible());effect.check()
   page.get_by_role('navigation',name='Fine tune sections').get_by_role('button',name='Tone',exact=True).click()
   page.locator('.ss-overlay-body').evaluate('(e)=>e.scrollTop=0')
   check('Fine tune has no cramped nested scroll area',page.locator('.ss-draft-review').evaluate('(e)=>e.scrollHeight<=e.clientHeight+2'))
   page.screenshot(path=str(OUT/'fine-tune.png'))
   page.get_by_role('button',name='▶ Audition draft',exact=True).click();page.wait_for_function("document.body.innerText.includes('Draft auditioned locally')")
   check('Generated draft can be auditioned before applying',page.evaluate('JSON.stringify(proof.getDoc())')==before)
   stop_draft=page.get_by_role('button',name='Stop draft preview',exact=True)
   check('A draft has an explicit Stop control',stop_draft.is_enabled());stop_draft.click()
   check('Stop draft preview stops without applying',stop_draft.is_disabled() and page.evaluate('JSON.stringify(proof.getDoc())')==before)
   page.get_by_role('button',name='Accept draft',exact=True).click()
   check('Accept applies the fine-tuned candidate',page.evaluate('proof.getDoc().theme.events.onCommit.filter.cutoff')==expected_cutoff)
   before=page.evaluate('JSON.stringify(proof.getDoc())')
   page.get_by_role('textbox',name='Describe the sound',exact=True).fill('Cancel this draft');page.evaluate('window.proofBackgroundHold=true')
   page.get_by_role('button',name='Generate sound',exact=True).click();page.get_by_role('button',name='Cancel draft',exact=True).click()
   page.wait_for_function('proofBackgroundLeases===0');page.get_by_role('button',name='Generate sound',exact=True).wait_for()
   check('Cancellation closes only its own conversation and keeps the sound',page.evaluate('JSON.stringify(proof.getDoc())')==before and page.evaluate('proof.getBackground().closed'))
   page.evaluate('(raw)=>{window.proofBackgroundHold=false;window.proofBackgroundInvalid=raw;}',json.dumps({'bad':1}))
   page.get_by_role('button',name='Generate sound',exact=True).click();page.get_by_role('alert').filter(has_text='valid SoundPatch/v1').wait_for()
   check('Invalid generated JSON cannot overwrite the selected sound',page.evaluate('JSON.stringify(proof.getDoc())')==before)
   page.evaluate('window.proofBackgroundInvalid=undefined')
   page.evaluate('window.proofBackgroundHold=true');page.get_by_role('textbox',name='Describe the sound',exact=True).fill('A draft while I keep editing')
   page.get_by_role('button',name='Generate sound',exact=True).click();page.get_by_role('button',name='Close dialog',exact=True).click()
   old_intensity=page.evaluate('proof.getDoc().theme.events.onCommit.intensity')
   intensity=page.locator('[data-parameter-id="ss-intensity"]');intensity.focus();intensity.press('ArrowUp')
   page.wait_for_function('(old)=>proof.getDoc().theme.events.onCommit.intensity!==old',arg=old_intensity)
   edited=page.evaluate('JSON.stringify(proof.getDoc())')
   page.get_by_role('button',name='Sound Draft',exact=True).click();page.evaluate('window.proofBackgroundHold=false');page.get_by_role('heading',name='Fine tune',exact=True).wait_for()
   check('Late results cannot overwrite edits made while generating',page.get_by_role('button',name='Accept draft',exact=True).is_disabled() and page.locator('input[data-parameter-id=ft-cutoff]').is_disabled() and page.evaluate('JSON.stringify(proof.getDoc())')==edited,{'acceptDisabled':page.get_by_role('button',name='Accept draft',exact=True).is_disabled(),'fieldsDisabled':page.locator('input[data-parameter-id=ft-cutoff]').is_disabled(),'intensity':page.evaluate('proof.getDoc().theme.events.onCommit.intensity')})
   page.get_by_role('button',name='Discard',exact=True).click()
   # Return JSON through the real review controls; no model response is fabricated.
   page.locator('.ss-draft-manual summary').click()
   patch=page.evaluate("JSON.parse(JSON.stringify(proof.getDoc()?.theme.events.onCommit??null))")
   if patch is None:
    patch=json.loads((ROOT/'assets/studio-palettes.json').read_text())[0]['events']['onCommit']
   patch['name']='Reviewed Session JSON'
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(patch))
   page.get_by_role('button',name='Review sound JSON',exact=True).click()
   check('Returned JSON requires explicit review before application',page.get_by_role('button',name='Accept draft',exact=True).is_visible() and page.evaluate("proof.getDoc()?.theme.events.onCommit.name??''")!='Reviewed Session JSON')
   page.get_by_role('button',name='Accept draft',exact=True).click()
   check('Accepted JSON reaches the selected sound',page.evaluate("proof.getDoc().theme.events.onCommit.name")=='Reviewed Session JSON')
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill('{"schemaVersion":"bad"}')
   page.get_by_role('button',name='Review sound JSON',exact=True).click()
   check('Invalid returned JSON cannot change sound',page.evaluate("proof.getDoc().theme.events.onCommit.name")=='Reviewed Session JSON')
   page.add_script_tag(url=f'http://127.0.0.1:{server.server_port}/evidence/workspace-upgrade/oracle.js')
   long_patch=page.evaluate("p=>({...p,fx:{...p.fx,delay:true},fxParameters:{...studioOracle.getFxParameters(p),delay:{time:.5,feedback:.7,mix:.2}}})",patch)
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(long_patch));page.get_by_role('button',name='Review sound JSON',exact=True).click()
   page.evaluate('''()=>{window.savedTimeout=window.setTimeout;window.longDraftTimers=[];window.setTimeout=(fn,ms,...args)=>{if(ms>6000)longDraftTimers.push(ms);return savedTimeout(fn,ms,...args);};}''')
   page.get_by_role('button',name='▶ Audition draft',exact=True).click();page.wait_for_function('longDraftTimers.length>0')
   check('Draft disposal follows long rendered effect tails instead of a six-second cutoff',page.evaluate('longDraftTimers.some(ms=>ms>10000)'))
   page.get_by_role('button',name='Stop draft preview',exact=True).click();page.evaluate('()=>{window.setTimeout=savedTimeout;}')
   page.get_by_role('button',name='Discard',exact=True).click()
   for filename in ['completion','bass']:
    original=json.loads((ROOT/f'tests/fixtures/quiet-drafts/{filename}.json').read_text())
    before=page.evaluate('JSON.stringify(proof.getDoc())')
    page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(original))
    page.get_by_role('button',name='Review sound JSON',exact=True).click()
    page.get_by_text('Very quiet.',exact=False).wait_for()
    check(f'{filename}: real quiet PCM is flagged before application',page.evaluate('JSON.stringify(proof.getDoc())')==before)
    audition=page.get_by_role('button',name='▶ Audition draft',exact=True)
    check(f'{filename}: draft audition can enable its own audio',audition.is_enabled())
    audition.click();page.wait_for_function("document.body.innerText.includes('Draft auditioned locally')")
    page.get_by_role('button',name='Balance draft level',exact=True).click()
    page.wait_for_function("document.querySelector('.ss-draft-level')?.textContent.includes('-18.')")
    check(f'{filename}: balancing stays in review until accepted',page.evaluate('JSON.stringify(proof.getDoc())')==before)
    page.get_by_role('button',name='Accept draft',exact=True).click()
    repaired=page.evaluate('proof.getDoc().theme.events.onCommit')
    measurements=page.evaluate('p=>studioOracle.measureDraftLevel(p)',repaired)
    check(f'{filename}: accepted patch has audible PCM and headroom',-18.5<measurements['peakDb']<-17.5,measurements)
    check(f'{filename}: notes, timing, filters and effects are preserved',all(original[k]==repaired[k] for k in ['baseFreq','chords','adsr','filter','fx','fxParameters','duration','seed']))
    (OUT/f'{filename}-balanced.json').write_text(json.dumps(repaired,indent=2)+'\n')
   silent={**original,'intensity':0}
   before=page.evaluate('JSON.stringify(proof.getDoc())')
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(silent))
   page.get_by_role('button',name='Review sound JSON',exact=True).click()
   page.get_by_text('Draft is silent or nearly silent.',exact=False).wait_for()
   check('A silent patch gets actionable diagnosis without automatic amplification',page.get_by_role('button',name='Balance draft level',exact=True).count()==0 and page.evaluate('JSON.stringify(proof.getDoc())')==before)
   outcome=page.evaluate('''async p=>{const before=JSON.stringify(p);try{await studioOracle.balanceDraftLevel(p);return false;}catch{return before===JSON.stringify(p);}}''',silent)
   check('Balancing rejects silence and preserves the original patch',outcome)
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(original))
   page.get_by_role('button',name='Review sound JSON',exact=True).click();page.get_by_text('Very quiet.',exact=False).wait_for()
   page.evaluate('''()=>{window.savedRender=OfflineAudioContext.prototype.startRendering;window.renderGate=new Promise(r=>window.releaseRender=r);window.gatedRenders=0;OfflineAudioContext.prototype.startRendering=function(){window.gatedRenders++;return Promise.all([savedRender.call(this),renderGate]).then(([buffer])=>buffer);};}''')
   page.get_by_role('button',name='Balance draft level',exact=True).click();page.wait_for_function('gatedRenders>0')
   page.get_by_role('button',name='Discard',exact=True).click();page.evaluate('releaseRender()');page.wait_for_timeout(500)
   check('Discard during balancing cannot restore or apply a stale draft',page.get_by_role('button',name='Accept draft',exact=True).count()==0 and page.evaluate('JSON.stringify(proof.getDoc())')==before)
   page.evaluate("OfflineAudioContext.prototype.startRendering=savedRender;const doc=proof.getDoc();doc.theme.masterGain=0;doc.revision++;localStorage.setItem('hermes.plugin.hermes-sonic-ui.local:default:sound-studio-v1',JSON.stringify(doc));")
   page.reload();page.get_by_role('button',name='Sound Draft',exact=True).click();page.locator('.ss-draft-manual summary').click()
   page.get_by_role('textbox',name='Returned SoundPatch/v1 JSON',exact=True).fill(json.dumps(original))
   page.get_by_role('button',name='Review sound JSON',exact=True).click()
   page.get_by_text('Master output is silent. Raise Master output',exact=False).wait_for()
   check('Muted master is diagnosed separately and kept unchanged',page.evaluate('proof.getDoc().theme.masterGain')==0)
   check('No browser errors',not REPORT['pageErrors'],REPORT['pageErrors'])
  finally:browser.close()
except Exception:REPORT['failure']=traceback.format_exc();print(REPORT['failure'])
finally:
 server.shutdown();(OUT/'verification.json').write_text(json.dumps(REPORT,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'passed':sum(row['pass'] for row in REPORT['checks']),'total':len(REPORT['checks']),'failure':REPORT.get('failure')},indent=2))
sys.exit(1 if 'failure' in REPORT else 0)
